package com.autoops.ai.service;import com.autoops.ai.tool.*;import org.springframework.stereotype.Service;import java.util.Map;@Service public class AIToolExecutor{private final AIToolRegistry registry;public AIToolExecutor(AIToolRegistry r){registry=r;}public Object execute(String name,Map<String,Object> args,Long user){var tool=registry.require(name);if(tool.risk()!=AITool.ToolRisk.READ&&tool.risk()!=AITool.ToolRisk.VALIDATE&&tool.risk()!=AITool.ToolRisk.PROPOSE)throw new SecurityException("AI tool is not permitted");return tool.execute(args,user);}}
